#[cfg(target_os = "windows")]
#[test]
fn interrupted_hosted_request_cannot_become_success() {
    let interrupted = AtomicBool::new(true);
    let error = generate_hosted(
        &HostedModelConfig {
            endpoint: "https://provider.example/v1/chat/completions".to_owned(),
            model: "example-model".to_owned(),
            auth_mode: HostedAuthMode::ApiKey,
            encrypted_secret_path: PathBuf::from("unused-protected-state"),
        },
        "hello",
        &interrupted,
    )
    .expect_err("interrupted inference must fail");
    assert_eq!(error.category, HostedFailureCategory::Interrupted);
    assert!(!error.retryable);
}

